const KEY='untangle-six-stories-v3',app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state||state.version!==3)state={version:3,view:'story',current:0,runs:{},done:[],answers:{},quizIndex:0,motion:true};let saved=true,frame=0,request=0;const images={};
function save(){if(state.view==='quiz'){state.quizRuns??={};state.quizRuns[state.quizMode]={index:state.quizIndex,feedback:state.quizFeedback};}try{localStorage.setItem(KEY,JSON.stringify(state));saved=true}catch{saved=false}}
function run(){return state.runs[state.current]??=( {node:'start',data:{},history:[]} )}
function button(label,action,extra='',cls='choice'){return `<button class="${cls}" data-action="${action}" ${extra}>${esc(label)}<span aria-hidden="true">↗</span></button>`}
function header(){return `<header><button data-action="map" class="brand" aria-label="Open chapter path">untangle<span>↗</span></button><div class="head-right"><span>${state.done.length}/6 discoveries</span><button class="icon" data-action="motion" aria-label="${state.motion?'Reduce':'Enable'} animations" aria-pressed="${!state.motion}">${state.motion?'Motion on':'Motion off'}</button></div></header>`}
function cards(v){return `<div class="visual-cards">${(v.cards||[]).map(([a,b])=>`<div class="visual-card"><small>${esc(a)}</small><strong>${esc(b)}</strong></div>`).join('')}</div>`}
function tv(on,label){return `<div class="company"><span class="company-label">${label}</span><div class="tv ${on?'on':'off'}"><div class="tv-glass">${on?'<div class="signal"></div><span>ON AIR</span>':'<span>ADS OFF</span>'}</div><i></i></div><div class="people ${on?'attract':''}" aria-hidden="true">${'<b></b>'.repeat(on?5:3)}</div></div>`}
function visual(v){const d=run().data;let inside='';
if(v.type?.startsWith('mini'))return miniVisual(v);
if(v.type==='ads'&&v.investigator&&!v.history)return marketBoard(v);
if(v.type==='ads'){inside=`<div class="scene-kicker">${esc(v.phase||(v.history?'Historical question':'Made-up experiment · practice coins'))}</div><div class="companies">${tv(v.a,v.investigator?(v.history?'Established company':'Company A'):(v.history?'Established company':'Your company'))}${tv(v.b,v.investigator?(v.history?'Competitor':'Company B'):'Rival')}</div>${v.money!==undefined?`<div class="receipt"><span>${v.bothMoney?'A and B · each keeps':v.investigator?'Company A · money left':'Money left after ads'}</span><strong><i class="coin">●</i> ${v.money}</strong><small>${esc(v.receipt)}</small></div>`:''}${v.rule?`<p class="model-rule">${esc(v.rule)}</p>`:''}`}
else if(v.type==='brands')inside=`<div class="scene-kicker">Recognition changes the starting point</div><div class="brands"><div><div class="shop">FAMILIAR</div><div class="people" aria-hidden="true">${'<b></b>'.repeat(5)}</div><small>Established brand</small></div><div><div class="shop new">NEW</div><div class="unknown">?</div><small>Newcomer</small></div></div>`;
else if(v.type==='rail'){inside=`<div class="rail-map"><div class="rail-line"></div><div class="stations">${['North','Central','South'].map(x=>`<span>●<small>${x}</small></span>`).join('')}</div><div class="train">▰ ▰ ▰</div>${v.stress==='expand'?'<div class="train rival">▰ ▰ ▰ ▰</div>':'<div class="train rival">▰ ▰</div>'}</div>${v.plan?`<div class="plan"><small>Your provisional plan</small><strong>${esc(d.plan)}</strong></div>`:''}${v.stress?`<p class="scene-kicker">${v.stress==='flat'?'Scenario: no demand growth':'Scenario: rival expands'}</p>`:''}${cards(v)}${v.note?`<div class="decision-note"><small>Your decision note</small><p>For now: <b>${esc(d.plan)}</b></p><p>Because: <b>${esc(d.reason)}</b></p><p>Reconsider if: <b>${esc(d.trigger)}</b></p></div>`:''}`}
else if(v.type==='quote'&&(v.win||v.loss)){inside=`<div class="invoice"><small>${v.win?'YOUR QUOTE WAS SELECTED':'SCOPE CHECK'}</small><strong>₹${Number(d.quote||70000).toLocaleString('en-IN')}</strong><div>${v.win?'Other quotes: ₹1,10,000 · ₹1,20,000':'Revised cost: ₹1,00,000'}</div>${v.loss?`<p class="shortfall">₹${(100000-(d.quote||70000)).toLocaleString('en-IN')} shortfall at your quote</p><small>20 pages assumed → 200 included</small>`:''}</div>`}
else {const motif={work:'<div class="desk"><div class="laptop">▥</div><div class="plant">♧</div></div>',meeting:`<div class="meeting-art ${v.shared?'shared':''}"><i>Engineering</i><div>${v.shared?'↔':'?'}</div><i>Sales</i></div>`,delivery:'<div class="road"><div class="van">▣<i></i><i></i></div><span>YOUR STORE → CUSTOMER</span></div>',quote:'<div class="paper-icon">≡<span>STUDIO / ESTIMATE</span></div>'}[v.type]||'';inside=motif+cards(v)+(v.caption?`<p class="scene-kicker">${esc(v.caption)}</p>`:'')}
return `<div class="visual ${esc(v.type)} ${v.spotlight?'spotlight':''}">${inside}</div>`}
function companion(line,mood){return `<div class="companion"><canvas width="400" height="400" id="fox" data-mood="${mood}" role="img" aria-label="Fox guide, ${mood}"></canvas><p>${esc(line)}</p></div>`}
async function fox(){cancelAnimationFrame(frame);const id=++request,c=document.querySelector('#fox');if(!c)return;const mood=c.dataset.mood||'speaking';try{if(!images[mood])images[mood]=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src='../lunch-rush/fox-b/'+mood+'-gesture-v3.png'});if(id!==request)return;const im=images[mood],ctx=c.getContext('2d'),start=performance.now();function draw(t){if(id!==request)return;const f=state.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches?Math.min(11,Math.floor((t-start)/140)):11,w=im.width/4,h=im.height/3;ctx.clearRect(0,0,400,400);ctx.drawImage(im,(f%4)*w,Math.floor(f/4)*h,w,h,0,0,400,400);if(f<11)frame=requestAnimationFrame(draw)}draw(start)}catch{c.outerHTML='<span class="fox-fallback" aria-label="Fox guide">🦊</span>'}}
function speechBeats(n){if(n.dialogue)return n.dialogue;const sentences=n.line.match(/[^.!?]+[.!?]+[”’"]?|[^.!?]+$/g)||[n.line];const beats=[];for(const sentence of sentences){const t=sentence.trim();if(!t)continue;if(beats.length&&(beats.at(-1).length+t.length)<160)beats[beats.length-1]+=' '+t;else beats.push(t)}return beats.length?beats:[n.line]}
function guideSpeech(line,mood){return `<div class="guide-stage"><canvas width="400" height="400" id="fox" data-mood="${mood}" role="img" aria-label="Fox guide, ${mood}"></canvas><div class="guide-bubble"><span class="speaker-label">YOUR GUIDE</span><h1 tabindex="-1">${esc(line)}</h1></div></div>`}
function storyView(){const s=STORIES[state.current],r=run(),n=s.nodes[r.node]||s.nodes.start;let choices=n.choices;
if(r.node==='evidence')choices=choices.map((x,i)=>({...x,label:(r.data['seen'+i]?'✓ ':'')+x.label}));
let extras='';if(state.current===5&&r.node==='evidence'&&[0,1,2,3].every(i=>r.data['seen'+i]))extras=button('Choose a plan','goto','data-next="plan"','primary');
if(state.current===5&&r.node==='future'&&r.data.flat&&r.data.expand)extras=button('Review my plan','goto','data-next="revise"','primary');
const beats=speechBeats(n),beat=Math.min(r.beat||0,beats.length-1),ready=beat===beats.length-1;
return `<main class="play guided"><div class="chapter-meta"><button data-action="map" aria-label="Pause and open chapter path">✕</button><span>STORY ${state.current+1} / 6 · ${esc(s.title)}</span></div><div class="progress"><span style="width:${r.node==='end'?100:Math.min(95,8+new Set(r.history).size*7)}%"></span></div><section class="screen guided-screen"><div class="conversation-focus">${guideSpeech(beats[beat],n.mood)}<div class="speech-step" aria-label="Message ${beat+1} of ${beats.length}">${beats.length>1?beats.map((_,i)=>`<i class="${i===beat?'active':''}"></i>`).join(''):''}</div></div><div class="supporting-scene" aria-label="Scene supporting the fox’s message">${visual(n.visual)}</div>${n.help?`<p class="mini-help">${esc(n.help)}</p>`:''}${n.input?`<label class="mini-answer-label" for="story-answer">Your explanation</label><textarea id="story-answer" data-story-field="${esc(n.input)}" placeholder="Type your explanation…">${esc(r.data[n.input]||'')}</textarea>`:''}<div class="answer-dock"><div class="choices ${ready?'answers-ready':''}">${ready?choices.map((c,i)=>button(c.label,'choose',`data-index="${i}"`)).join('')+extras:button('Continue','speech','','primary')}</div>${state.current===0&&n.visual.investigator&&!n.visual.history&&ready?'<details><summary>How this example works</summary><p>Two companies divide 200 coins. Each advertiser pays 40. Both advertise: 60 left each. Neither: 100 each. Only one advertises: 120 left for it, 40 for the other. Other costs excluded.</p></details>':''}</div></section><footer>${saved?'Saved in this browser':'Saving unavailable. Keep this tab open.'}<button data-action="map">Pause</button></footer></main>`}

function mapView(){return `<main class="map"><div class="map-heading"><div class="eyebrow">GAME THEORY · CHAPTER 01</div><h1>You’re not<br>choosing alone.</h1><p>Six discoveries about the moves we make—and the people who change what happens next.</p><small>Preview mode · all stories open for testing</small></div><div class="trail">${STORIES.map((s,i)=>`<div class="trail-stop ${state.done.includes(i)?'complete':''}"><button class="node" data-action="start" data-index="${i}" aria-label="${esc(s.title)}">${state.done.includes(i)?'✓':s.icon}</button><div><small>${state.done.includes(i)?'DISCOVERED':state.runs[i]?'CONTINUE':'EXPLORE'}</small><h2>${esc(s.title)}</h2><span>${esc(s.concept)}</span></div></div>`).join('')}</div><div class="quiz-links"><h2>Make the ideas yours.</h2><p>12 questions with feedback, then 12 fresh situations.</p>${button('Check what you learned','quiz','data-mode="C"')}${button('Fresh practice','quiz','data-mode="P"')}</div></main>`}
function complete(){const s=STORIES[state.current];return `<main class="play"><section class="screen"><div class="eyebrow">DISCOVERY SAVED</div><h1>${esc(s.concept)}</h1><div class="badge">✓</div>${companion(s.takeaway,'celebrating')}<div class="choices">${button(state.current<5?'Next: '+STORIES[state.current+1].title:'Check what you learned',state.current<5?'nextstory':'quiz',state.current<5?'':'data-mode="C"','primary')}${button('Back to chapter path','map')}</div><small>Saved once. Replays do not add extra discoveries.</small></section></main>`}
function quizView(){const mode=state.quizMode||'C',items=QUESTIONS.filter(q=>q.id[0]===mode),idx=state.quizIndex,q=items[idx];if(!q){const wrong=items.filter(q=>state.answers[q.id]!==q.key),score=12-wrong.length;return `<main class="play"><section class="screen"><div class="eyebrow">${mode==='C'?'UNDERSTANDING CHECK':'FRESH PRACTICE'} COMPLETE</div><h1>${score} / 12</h1><p>One set is a snapshot, not proof of lasting mastery.</p>${wrong.length?'<h2>Ideas to revisit</h2>'+[...new Set(wrong.map(q=>Math.floor((Number(q.id.slice(1))-1)/2)))].map(i=>button(STORIES[i].concept,'start',`data-index="${i}"`)).join(''):'<p>You explained each idea correctly in this set.</p>'}${mode==='P'?items.map(q=>`<details><summary>${esc(q.title)} · ${state.answers[q.id]===q.key?'Correct':'Review'}</summary><p>Your answer: ${esc(q.options[state.answers[q.id]])}</p><p>${esc(q.explain)}</p></details>`).join(''):''}<div class="choices">${button(mode==='C'?'Try fresh practice':'Return to chapter path',mode==='C'?'quiz':'map',mode==='C'?'data-mode="P"':'','primary')}</div></section></main>`}
const answer=state.answers[q.id],feedback=mode==='C'&&state.quizFeedback;
return `<main class="play"><div class="chapter-meta"><button data-action="map">← Pause</button><span>${idx+1} / 12 · ${mode==='C'?'Check':'Practice'}</span></div><div class="progress"><span style="width:${idx/12*100}%"></span></div><section class="screen"><div class="eyebrow">${esc(q.title)}</div><h1 tabindex="-1">${feedback?(answer===q.key?'That fits the evidence.':'Let’s look at the cause.'):esc(q.prompt)}</h1>${feedback?companion(q.explain,answer===q.key?'celebrating':'thinking'):'<p class="quiz-hint">'+(mode==='P'?'Choose an answer. Explanations appear after the full set.':'Choose an answer, then explore the reasoning.')+'</p>'}<div class="choices">${feedback?button('Next question','qnext','','primary'):q.options.map((o,i)=>button(o,'answer',`data-index="${i}"`)).join('')}</div></section></main>`}
function animateConsequence(){if(state.view==='story'&&state.current===0&&STORIES[0].nodes[run().node]?.visual.type==='miniMarket'){miniAnimate(++sceneToken);return;}const r=run(),n=STORIES[state.current]?.nodes[r.node];const previous={alone:[true,true],both_after_alone:[false,true],together:[true,true],alone_after_both:[false,false]}[r.node];if(state.view!=='story'||state.current!==0||!previous||!state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const stage=document.querySelector('.supporting-scene');if(!stage)return;const token=++sceneToken;playMarketTransition(stage,{...n.visual,a:previous[0],b:previous[1]},n.visual,()=>token===sceneToken);}

app.addEventListener('input',e=>{if(e.target.dataset.storyField){run().data[e.target.dataset.storyField]=e.target.value;save();}});
let sceneToken=0;
function render(focus=true){sceneToken++;document.body.classList.toggle('reduce',!state.motion);document.body.classList.toggle('in-lesson',state.view==='story');app.innerHTML=header()+(state.view==='map'?mapView():state.view==='complete'?complete():state.view==='quiz'?quizView():storyView());fox();animateConsequence();if(focus){document.querySelector('h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}}
function transition(next){const r=run();r.history.push(r.node);r.node=next;r.beat=0;save();render()}
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action,i=Number(b.dataset.index);if(a==='map')state.view='map';else if(a==='motion'){state.motion=!state.motion;}else if(a==='start'){state.current=i;state.view='story';if(state.done.includes(i))state.runs[i]={node:'start',data:{},history:[]};}else if(a==='speech'){run().beat=(run().beat||0)+1;}else if(a==='choose'){const r=run(),node=STORIES[state.current].nodes[r.node];if((r.beat||0)<speechBeats(node).length-1)return;const c=node.choices[i];Object.assign(r.data,c.set||{});r.lastChoice=c.label;if(state.current===0&&['keep','stop'].includes(r.node)){r.data.previousAds=r.node==='keep';r.data.previousMoney=r.node==='keep'?60:40;}if(c.next==='finish'){if(!state.done.includes(state.current))state.done.push(state.current);state.view='complete';}else return transition(c.next);}else if(a==='goto')return transition(b.dataset.next);else if(a==='nextstory'){state.current++;state.view='story';}else if(a==='quiz'){const mode=b.dataset.mode||'C';state.quizMode=mode;state.view='quiz';const items=QUESTIONS.filter(q=>q.id[0]===mode);const resume=state.quizRuns?.[mode];state.quizIndex=resume?resume.index:items.findIndex(q=>state.answers[q.id]===undefined);if(state.quizIndex<0)state.quizIndex=12;state.quizFeedback=resume?.feedback||false;}else if(a==='answer'){const q=QUESTIONS.filter(q=>q.id[0]===state.quizMode)[state.quizIndex];state.answers[q.id]=i;if(state.quizMode==='C')state.quizFeedback=true;else state.quizIndex++;}else if(a==='qnext'){state.quizIndex++;state.quizFeedback=false;}save();render();});
if(state.investigatorRevision!==1){if(state.runs[0]){state.openingArchive??=[];state.openingArchive.push(state.runs[0]);delete state.runs[0];}state.investigatorRevision=1;save();}
if(state.runs[0]?.node==='rivals'){state.runs[0].node='starting_money';state.runs[0].beat=0;save();}
if(state.storyboardRevision!==1){if(state.runs[0]){state.openingArchive??=[];state.openingArchive.push(state.runs[0]);delete state.runs[0];}state.storyboardRevision=1;save();}
if(state.openingContextRevision!==1){if(state.current===0&&state.view==='story'&&['start','baseline','decision'].includes(run().node)){run().node='start';run().beat=0;}state.openingContextRevision=1;save();}
render(false);
